-- Arcana Lab: complete SQLite setup (schema + 78 cards + correspondence metadata)
-- Usage: sqlite3 arcana_lab.sqlite < database/setup_arcana_lab.sql
-- All meanings are concise original learning syntheses; correspondence attributions are tradition-specific.
PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS cards (
    card_id TEXT PRIMARY KEY,
    card_name TEXT NOT NULL UNIQUE,
    arcana TEXT NOT NULL CHECK (arcana IN ('Major','Minor')),
    suit TEXT NOT NULL,
    rank INTEGER NOT NULL,
    element TEXT,
    upright_keywords TEXT NOT NULL,
    reversed_keywords TEXT NOT NULL,
    technical_upright TEXT NOT NULL,
    technical_reversed TEXT NOT NULL,
    child_explanation TEXT NOT NULL,
    imagery_observation TEXT NOT NULL,
    reflection_prompt_1 TEXT NOT NULL,
    reflection_prompt_2 TEXT NOT NULL,
    astrological_correspondence TEXT,
    correspondence_system TEXT,
    source_note TEXT
);

CREATE TABLE IF NOT EXISTS correspondences (
    correspondence_id INTEGER PRIMARY KEY AUTOINCREMENT,
    layer TEXT NOT NULL,
    tarot_group TEXT NOT NULL,
    element TEXT,
    zodiac_signs TEXT,
    traditional_sign_rulers TEXT,
    scope TEXT,
    system TEXT,
    caution TEXT
);

CREATE TABLE IF NOT EXISTS readings (
    reading_id INTEGER PRIMARY KEY AUTOINCREMENT,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    question TEXT NOT NULL,
    life_domain TEXT NOT NULL,
    context TEXT,
    spread_type TEXT NOT NULL,
    draw_method TEXT NOT NULL,
    initial_observation TEXT,
    overall_interpretation TEXT,
    key_insight TEXT,
    action_commitment TEXT,
    theme_tags TEXT,
    follow_up_due TEXT
);

CREATE TABLE IF NOT EXISTS reading_cards (
    reading_card_id INTEGER PRIMARY KEY AUTOINCREMENT,
    reading_id INTEGER NOT NULL REFERENCES readings(reading_id) ON DELETE CASCADE,
    position_index INTEGER NOT NULL,
    position_label TEXT NOT NULL,
    card_id TEXT NOT NULL REFERENCES cards(card_id),
    orientation TEXT NOT NULL CHECK (orientation IN ('Upright','Reversed')),
    visual_observation TEXT,
    personal_interpretation TEXT,
    UNIQUE(reading_id, position_index)
);

CREATE TABLE IF NOT EXISTS study_reviews (
    review_id INTEGER PRIMARY KEY AUTOINCREMENT,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    card_id TEXT NOT NULL REFERENCES cards(card_id),
    quiz_score INTEGER NOT NULL,
    quiz_total INTEGER NOT NULL,
    recall_rating INTEGER CHECK (recall_rating BETWEEN 1 AND 5),
    minutes_spent INTEGER,
    next_review_at TEXT,
    notes TEXT
);

CREATE TABLE IF NOT EXISTS followups (
    followup_id INTEGER PRIMARY KEY AUTOINCREMENT,
    reading_id INTEGER NOT NULL REFERENCES readings(reading_id) ON DELETE CASCADE,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    outcome_note TEXT,
    action_completed INTEGER NOT NULL DEFAULT 0 CHECK (action_completed IN (0,1)),
    alignment_rating INTEGER CHECK (alignment_rating BETWEEN 1 AND 5),
    emotion_label TEXT
);

CREATE INDEX IF NOT EXISTS idx_readings_created_at ON readings(created_at);
CREATE INDEX IF NOT EXISTS idx_readings_domain ON readings(life_domain);
CREATE INDEX IF NOT EXISTS idx_reading_cards_card_id ON reading_cards(card_id);
CREATE INDEX IF NOT EXISTS idx_study_reviews_created_at ON study_reviews(created_at);
CREATE INDEX IF NOT EXISTS idx_followups_reading_id ON followups(reading_id);

CREATE VIEW IF NOT EXISTS v_reading_detail AS
SELECT
    r.reading_id, r.created_at, r.question, r.life_domain, r.context,
    r.spread_type, r.draw_method, r.initial_observation,
    r.overall_interpretation, r.key_insight, r.action_commitment,
    r.theme_tags, rc.position_index, rc.position_label,
    c.card_name, c.arcana, c.suit, c.element, rc.orientation,
    rc.visual_observation, rc.personal_interpretation
FROM readings r
JOIN reading_cards rc ON rc.reading_id = r.reading_id
JOIN cards c ON c.card_id = rc.card_id;


BEGIN TRANSACTION;

INSERT INTO cards (card_id, card_name, arcana, suit, rank, element, upright_keywords, reversed_keywords, technical_upright, technical_reversed, child_explanation, imagery_observation, reflection_prompt_1, reflection_prompt_2, astrological_correspondence, correspondence_system, source_note) VALUES ('major_00_the_fool', 'The Fool', 'Major', 'Major Arcana', 0, 'Air', 'Beginnings, openness, spontaneity, trust', 'Recklessness, hesitation, avoidable risk', 'Beginnings, openness, spontaneity, trust. Use the image, question and spread position to refine the interpretation.', 'Recklessness, hesitation, avoidable risk. Reversal can indicate blockage, excess, internalization or an alternate expression; it is not automatically the opposite.', 'A new journey begins with curiosity; stay open but pay attention.', 'A traveler stands at a cliff with a small bag and a white dog.', 'What new beginning am I approaching?', 'What would a careful first step look like?', 'Air', 'Golden Dawn / traditional esoteric attribution; interpret within this system', 'Original concise learning synthesis; consult Waite (1911) and Book T for historical comparison.');
INSERT INTO cards (card_id, card_name, arcana, suit, rank, element, upright_keywords, reversed_keywords, technical_upright, technical_reversed, child_explanation, imagery_observation, reflection_prompt_1, reflection_prompt_2, astrological_correspondence, correspondence_system, source_note) VALUES ('major_01_the_magician', 'The Magician', 'Major', 'Major Arcana', 1, NULL, 'Agency, skill, focus, resourcefulness', 'Scattered energy, manipulation, unused potential', 'Agency, skill, focus, resourcefulness. Use the image, question and spread position to refine the interpretation.', 'Scattered energy, manipulation, unused potential. Reversal can indicate blockage, excess, internalization or an alternate expression; it is not automatically the opposite.', 'You have tools available; learn how to use them deliberately.', 'A figure stands at a table with the four suit symbols and one hand raised.', 'Which resources or skills do I already have?', 'Where am I scattering my attention?', 'Mercury', 'Golden Dawn / traditional esoteric attribution; interpret within this system', 'Original concise learning synthesis; consult Waite (1911) and Book T for historical comparison.');
INSERT INTO cards (card_id, card_name, arcana, suit, rank, element, upright_keywords, reversed_keywords, technical_upright, technical_reversed, child_explanation, imagery_observation, reflection_prompt_1, reflection_prompt_2, astrological_correspondence, correspondence_system, source_note) VALUES ('major_02_the_high_priestess', 'The High Priestess', 'Major', 'Major Arcana', 2, NULL, 'Intuition, inner knowledge, silence, observation', 'Secrets, disconnection, confusion, ignored inner signals', 'Intuition, inner knowledge, silence, observation. Use the image, question and spread position to refine the interpretation.', 'Secrets, disconnection, confusion, ignored inner signals. Reversal can indicate blockage, excess, internalization or an alternate expression; it is not automatically the opposite.', 'Be quiet, observe, and notice what you have not yet put into words.', 'A seated figure between two pillars holds a scroll; a veil hangs behind her.', 'What do I sense but have not examined?', 'What evidence would help me distinguish intuition from assumption?', 'Moon', 'Golden Dawn / traditional esoteric attribution; interpret within this system', 'Original concise learning synthesis; consult Waite (1911) and Book T for historical comparison.');
INSERT INTO cards (card_id, card_name, arcana, suit, rank, element, upright_keywords, reversed_keywords, technical_upright, technical_reversed, child_explanation, imagery_observation, reflection_prompt_1, reflection_prompt_2, astrological_correspondence, correspondence_system, source_note) VALUES ('major_03_the_empress', 'The Empress', 'Major', 'Major Arcana', 3, NULL, 'Nurturing, creativity, growth, abundance', 'Overgiving, stagnation, dependence, neglect', 'Nurturing, creativity, growth, abundance. Use the image, question and spread position to refine the interpretation.', 'Overgiving, stagnation, dependence, neglect. Reversal can indicate blockage, excess, internalization or an alternate expression; it is not automatically the opposite.', 'Care for what you want to grow, including your own body and projects.', 'A crowned figure sits in a fertile landscape with wheat and flowing water.', 'What needs nourishment to grow?', 'Where am I giving more than I can sustain?', 'Venus', 'Golden Dawn / traditional esoteric attribution; interpret within this system', 'Original concise learning synthesis; consult Waite (1911) and Book T for historical comparison.');
INSERT INTO cards (card_id, card_name, arcana, suit, rank, element, upright_keywords, reversed_keywords, technical_upright, technical_reversed, child_explanation, imagery_observation, reflection_prompt_1, reflection_prompt_2, astrological_correspondence, correspondence_system, source_note) VALUES ('major_04_the_emperor', 'The Emperor', 'Major', 'Major Arcana', 4, NULL, 'Structure, responsibility, boundaries, leadership', 'Rigidity, control, domination, inflexibility', 'Structure, responsibility, boundaries, leadership. Use the image, question and spread position to refine the interpretation.', 'Rigidity, control, domination, inflexibility. Reversal can indicate blockage, excess, internalization or an alternate expression; it is not automatically the opposite.', 'Build a stable structure and take responsibility for your decisions.', 'A ruler sits on a stone throne decorated with rams.', 'Where do I need structure or clearer boundaries?', 'Where has control become rigidity?', 'Aries', 'Golden Dawn / traditional esoteric attribution; interpret within this system', 'Original concise learning synthesis; consult Waite (1911) and Book T for historical comparison.');
INSERT INTO cards (card_id, card_name, arcana, suit, rank, element, upright_keywords, reversed_keywords, technical_upright, technical_reversed, child_explanation, imagery_observation, reflection_prompt_1, reflection_prompt_2, astrological_correspondence, correspondence_system, source_note) VALUES ('major_05_the_hierophant', 'The Hierophant', 'Major', 'Major Arcana', 5, NULL, 'Tradition, learning, mentorship, shared values', 'Conformity, dogma, rebellion without reflection', 'Tradition, learning, mentorship, shared values. Use the image, question and spread position to refine the interpretation.', 'Conformity, dogma, rebellion without reflection. Reversal can indicate blockage, excess, internalization or an alternate expression; it is not automatically the opposite.', 'Learn from a tradition, then decide consciously what deserves to be kept.', 'A teacher blesses two students before a symbolic doorway.', 'Which beliefs or teachers shape my choices?', 'What do I follow without questioning?', 'Taurus', 'Golden Dawn / traditional esoteric attribution; interpret within this system', 'Original concise learning synthesis; consult Waite (1911) and Book T for historical comparison.');
INSERT INTO cards (card_id, card_name, arcana, suit, rank, element, upright_keywords, reversed_keywords, technical_upright, technical_reversed, child_explanation, imagery_observation, reflection_prompt_1, reflection_prompt_2, astrological_correspondence, correspondence_system, source_note) VALUES ('major_06_the_lovers', 'The Lovers', 'Major', 'Major Arcana', 6, NULL, 'Choice, alignment, connection, values', 'Misalignment, indecision, divided priorities', 'Choice, alignment, connection, values. Use the image, question and spread position to refine the interpretation.', 'Misalignment, indecision, divided priorities. Reversal can indicate blockage, excess, internalization or an alternate expression; it is not automatically the opposite.', 'A meaningful choice asks you to align behavior with values.', 'Two figures stand beneath an angel in a garden.', 'Which choice best matches my values?', 'Where are my actions out of alignment?', 'Gemini', 'Golden Dawn / traditional esoteric attribution; interpret within this system', 'Original concise learning synthesis; consult Waite (1911) and Book T for historical comparison.');
INSERT INTO cards (card_id, card_name, arcana, suit, rank, element, upright_keywords, reversed_keywords, technical_upright, technical_reversed, child_explanation, imagery_observation, reflection_prompt_1, reflection_prompt_2, astrological_correspondence, correspondence_system, source_note) VALUES ('major_07_the_chariot', 'The Chariot', 'Major', 'Major Arcana', 7, NULL, 'Direction, discipline, determination, self-command', 'Force, impatience, lack of direction, competing impulses', 'Direction, discipline, determination, self-command. Use the image, question and spread position to refine the interpretation.', 'Force, impatience, lack of direction, competing impulses. Reversal can indicate blockage, excess, internalization or an alternate expression; it is not automatically the opposite.', 'Choose a direction and guide competing forces toward it.', 'A charioteer stands between two contrasting sphinxes.', 'What direction am I choosing?', 'Which competing impulses need coordination?', 'Cancer', 'Golden Dawn / traditional esoteric attribution; interpret within this system', 'Original concise learning synthesis; consult Waite (1911) and Book T for historical comparison.');
