INSERT INTO cards (card_id, card_name, arcana, suit, rank, element, upright_keywords, reversed_keywords, technical_upright, technical_reversed, child_explanation, imagery_observation, reflection_prompt_1, reflection_prompt_2, astrological_correspondence, correspondence_system, source_note) VALUES ('wands_01_ace_wands', 'Ace of Wands', 'Minor', 'Wands', 1, 'Fire', 'Spark, inspiration, initiative, creative potential', 'Delays, low energy, unused potential', 'A new source of energy or creative possibility; the idea needs action to become real.', 'A blocked start, fading enthusiasm, or an idea that has not been given room.', 'A match has been lit. Decide what you want to build with its energy.', 'A hand offers a sprouting wand from a cloud.', 'What idea genuinely energizes me?', 'What small action would turn inspiration into movement?', 'Elemental attribution: Fire', 'Golden Dawn / Book T suit-element attribution', 'Original concise learning synthesis; Book T correspondence is tradition-specific, not universal.');
INSERT INTO cards (card_id, card_name, arcana, suit, rank, element, upright_keywords, reversed_keywords, technical_upright, technical_reversed, child_explanation, imagery_observation, reflection_prompt_1, reflection_prompt_2, astrological_correspondence, correspondence_system, source_note) VALUES ('wands_02_two_wands', 'Two of Wands', 'Minor', 'Wands', 2, 'Fire', 'Planning, vision, possibility, choice', 'Fear of the unknown, poor planning, limited perspective', 'Considering future possibilities and choosing a direction beyond the familiar.', 'Staying in the comfort zone, planning without commitment, or overlooking constraints.', 'You can see two paths. Compare them before choosing one.', 'A person looks outward from a wall while holding a globe and a wand.', 'What future am I considering?', 'What information do I need before choosing?', 'Mars in Aries — decan 1 of 3', 'Golden Dawn / Book T decan attribution', 'Original concise learning synthesis; Book T correspondence is tradition-specific, not universal.');
INSERT INTO cards (card_id, card_name, arcana, suit, rank, element, upright_keywords, reversed_keywords, technical_upright, technical_reversed, child_explanation, imagery_observation, reflection_prompt_1, reflection_prompt_2, astrological_correspondence, correspondence_system, source_note) VALUES ('wands_03_three_wands', 'Three of Wands', 'Minor', 'Wands', 3, 'Fire', 'Expansion, foresight, progress, exploration', 'Delays, narrow planning, frustration', 'Early progress creates a wider view; prepare for the next stage.', 'Expectations outpace preparation, or progress is delayed by missing details.', 'Your boat is on the water. Check where it is going and prepare for its arrival.', 'A figure watches ships from a high shore.', 'Where is momentum beginning?', 'What must be prepared for the next stage?', 'Sun in Aries — decan 2 of 3', 'Golden Dawn / Book T decan attribution', 'Original concise learning synthesis; Book T correspondence is tradition-specific, not universal.');
