INSERT INTO cards (card_id, card_name, arcana, suit, rank, element, upright_keywords, reversed_keywords, technical_upright, technical_reversed, child_explanation, imagery_observation, reflection_prompt_1, reflection_prompt_2, astrological_correspondence, correspondence_system, source_note) VALUES ('swords_05_five_swords', 'Five of Swords', 'Minor', 'Swords', 5, 'Air', 'Conflict, self-interest, tension, hollow victory', 'Reconciliation, accountability, unresolved conflict', 'Conflict may produce a win that damages trust or shared goals.', 'An attempt to repair conflict, or refusal to acknowledge harm.', 'Winning an argument can still hurt everyone. Ask what the win costs.', 'A figure gathers swords while others walk away.', 'What is the cost of this conflict?', 'What would accountability or repair require?', 'Venus in Aquarius — decan 1 of 3', 'Golden Dawn / Book T decan attribution', 'Original concise learning synthesis; Book T correspondence is tradition-specific, not universal.');
INSERT INTO cards (card_id, card_name, arcana, suit, rank, element, upright_keywords, reversed_keywords, technical_upright, technical_reversed, child_explanation, imagery_observation, reflection_prompt_1, reflection_prompt_2, astrological_correspondence, correspondence_system, source_note) VALUES ('swords_06_six_swords', 'Six of Swords', 'Minor', 'Swords', 6, 'Air', 'Transition, perspective, gradual recovery, moving on', 'Resistance, unfinished transition, returning trouble', 'A gradual move away from difficulty toward calmer conditions.', 'The transition is delayed or emotional baggage travels with you.', 'You are moving to a calmer place, one step at a time.', 'A boat carries passengers and swords across water.', 'What am I moving away from?', 'What needs to come with me, and what can be left behind?', 'Mercury in Aquarius — decan 2 of 3', 'Golden Dawn / Book T decan attribution', 'Original concise learning synthesis; Book T correspondence is tradition-specific, not universal.');
INSERT INTO cards (card_id, card_name, arcana, suit, rank, element, upright_keywords, reversed_keywords, technical_upright, technical_reversed, child_explanation, imagery_observation, reflection_prompt_1, reflection_prompt_2, astrological_correspondence, correspondence_system, source_note) VALUES ('swords_07_seven_swords', 'Seven of Swords', 'Minor', 'Swords', 7, 'Air', 'Strategy, discretion, independence, evasion', 'Exposure, confession, poor strategy, self-deception', 'A situation calls for careful strategy; examine honesty and hidden motives.', 'A plan is exposed, or avoidance and self-deception become difficult to sustain.', 'Think carefully, but do not trick yourself or other people.', 'A figure carries five swords away from a camp.', 'Where is discretion useful?', 'Am I avoiding a direct conversation?', 'Moon in Aquarius — decan 3 of 3', 'Golden Dawn / Book T decan attribution', 'Original concise learning synthesis; Book T correspondence is tradition-specific, not universal.');
INSERT INTO cards (card_id, card_name, arcana, suit, rank, element, upright_keywords, reversed_keywords, technical_upright, technical_reversed, child_explanation, imagery_observation, reflection_prompt_1, reflection_prompt_2, astrological_correspondence, correspondence_system, source_note) VALUES ('swords_08_eight_swords', 'Eight of Swords', 'Minor', 'Swords', 8, 'Air', 'Restriction, self-limitation, fear, helplessness', 'New perspective, release, recognizing options', 'A sense of restriction may be reinforced by assumptions or fear.', 'Options become visible, or a limiting belief is challenged.', 'You may have more choices than you can see right now.', 'A blindfolded figure is loosely bound among swords.', 'Which belief makes me feel stuck?', 'What option becomes visible if I test that belief?', 'Jupiter in Gemini — decan 1 of 3', 'Golden Dawn / Book T decan attribution', 'Original concise learning synthesis; Book T correspondence is tradition-specific, not universal.');
INSERT INTO cards (card_id, card_name, arcana, suit, rank, element, upright_keywords, reversed_keywords, technical_upright, technical_reversed, child_explanation, imagery_observation, reflection_prompt_1, reflection_prompt_2, astrological_correspondence, correspondence_system, source_note) VALUES ('swords_09_nine_swords', 'Nine of Swords', 'Minor', 'Swords', 9, 'Air', 'Worry, guilt, rumination, sleeplessness', 'Relief, disclosure, persistent anxiety', 'Thoughts become distressing when worry and imagined outcomes dominate.', 'Worries may be shared and reduced, or remain difficult to contain.', 'Your mind is replaying scary possibilities. Separate what happened from what might happen.', 'A person sits upright in bed with hands over their face.', 'What thought keeps repeating?', 'What is known, imagined, and still unknown?', 'Mars in Gemini — decan 2 of 3', 'Golden Dawn / Book T decan attribution', 'Original concise learning synthesis; Book T correspondence is tradition-specific, not universal.');
INSERT INTO cards (card_id, card_name, arcana, suit, rank, element, upright_keywords, reversed_keywords, technical_upright, technical_reversed, child_explanation, imagery_observation, reflection_prompt_1, reflection_prompt_2, astrological_correspondence, correspondence_system, source_note) VALUES ('swords_10_ten_swords', 'Ten of Swords', 'Minor', 'Swords', 10, 'Air', 'Ending, exhaustion, painful conclusion, limit', 'Recovery, survival, fear of another ending', 'A difficult cycle reaches a limit or conclusion.', 'Recovery begins, or fear makes it hard to trust that the worst has passed.', 'Something has reached its end. The next step is recovery.', 'A figure lies beneath ten swords as dawn appears.', 'What has clearly reached its limit?', 'What would recovery look like in practical terms?', 'Sun in Gemini — decan 3 of 3', 'Golden Dawn / Book T decan attribution', 'Original concise learning synthesis; Book T correspondence is tradition-specific, not universal.');
INSERT INTO cards (card_id, card_name, arcana, suit, rank, element, upright_keywords, reversed_keywords, technical_upright, technical_reversed, child_explanation, imagery_observation, reflection_prompt_1, reflection_prompt_2, astrological_correspondence, correspondence_system, source_note) VALUES ('swords_11_page_swords', 'Page of Swords', 'Minor', 'Swords', 11, 'Air', 'Curiosity, alertness, questions, new ideas', 'Gossip, defensiveness, scattered thinking', 'A questioning mind gathers information and tests ideas.', 'Reacting before checking facts or using information carelessly.', 'Ask questions and check what is true before repeating something.', 'A young figure holds a sword against a windy sky.', 'What do I need to investigate?', 'How will I verify what I hear?', 'Court elemental formula: Earth of Air; no single zodiac sign assigned in this base model', 'Golden Dawn court elemental formula; sign attribution intentionally omitted', 'Original concise learning synthesis; Book T correspondence is tradition-specific, not universal.');
INSERT INTO cards (card_id, card_name, arcana, suit, rank, element, upright_keywords, reversed_keywords, technical_upright, technical_reversed, child_explanation, imagery_observation, reflection_prompt_1, reflection_prompt_2, astrological_correspondence, correspondence_system, source_note) VALUES ('swords_12_knight_swords', 'Knight of Swords', 'Minor', 'Swords', 12, 'Air', 'Directness, speed, conviction, decisive thought', 'Aggression, haste, poor listening, scattered plans', 'Fast, determined action guided by a strong idea.', 'Rushing into conflict or mistaking certainty for accuracy.', 'Move with purpose, but listen and check your direction.', 'An armored rider charges forward with a raised sword.', 'Where is decisive communication needed?', 'What might I miss by moving too quickly?', 'Court elemental formula: Air of Air; no single zodiac sign assigned in this base model', 'Golden Dawn court elemental formula; sign attribution intentionally omitted', 'Original concise learning synthesis; Book T correspondence is tradition-specific, not universal.');
INSERT INTO cards (card_id, card_name, arcana, suit, rank, element, upright_keywords, reversed_keywords, technical_upright, technical_reversed, child_explanation, imagery_observation, reflection_prompt_1, reflection_prompt_2, astrological_correspondence, correspondence_system, source_note) VALUES ('swords_13_queen_swords', 'Queen of Swords', 'Minor', 'Swords', 13, 'Air', 'Discernment, independence, honesty, boundaries', 'Coldness, cynicism, harsh judgment, guardedness', 'Clear judgment combines experience, direct communication and healthy boundaries.', 'Clarity hardens into cynicism, or pain makes connection difficult.', 'Think clearly, speak honestly, and be fair to yourself and others.', 'A queen holds an upright sword beneath clouds and wind.', 'What are the facts, separate from my assumptions?', 'What boundary would make this situation clearer?', 'Court elemental formula: Water of Air; no single zodiac sign assigned in this base model', 'Golden Dawn court elemental formula; sign attribution intentionally omitted', 'Original concise learning synthesis; Book T correspondence is tradition-specific, not universal.');
INSERT INTO cards (card_id, card_name, arcana, suit, rank, element, upright_keywords, reversed_keywords, technical_upright, technical_reversed, child_explanation, imagery_observation, reflection_prompt_1, reflection_prompt_2, astrological_correspondence, correspondence_system, source_note) VALUES ('swords_14_king_swords', 'King of Swords', 'Minor', 'Swords', 14, 'Air', 'Reason, ethics, authority, strategic judgment', 'Rigidity, misuse of authority, detached judgment', 'Principled reasoning and consistent standards guide decisions.', 'Logic is used to dominate, or rules are applied without context.', 'Use your mind fairly and take responsibility for your decisions.', 'A king sits upright with a sword in a clear sky.', 'What principle should guide this decision?', 'Am I applying the same standard to everyone, including myself?', 'Court elemental formula: Fire of Air; no single zodiac sign assigned in this base model', 'Golden Dawn court elemental formula; sign attribution intentionally omitted', 'Original concise learning synthesis; Book T correspondence is tradition-specific, not universal.');
INSERT INTO cards (card_id, card_name, arcana, suit, rank, element, upright_keywords, reversed_keywords, technical_upright, technical_reversed, child_explanation, imagery_observation, reflection_prompt_1, reflection_prompt_2, astrological_correspondence, correspondence_system, source_note) VALUES ('pentacles_01_ace_pentacles', 'Ace of Pentacles', 'Minor', 'Pentacles', 1, 'Earth', 'Opportunity, resources, health, practical beginning', 'Missed opportunity, poor planning, instability', 'A tangible opportunity or practical foundation can be developed through consistent effort.', 'A useful opportunity is delayed, mishandled, or not yet practical.', 'A seed is in your hand. Give it a real place to grow.', 'A hand offers a pentacle above a garden path.', 'What practical opportunity is available?', 'What resources or habits would help it grow?', 'Elemental attribution: Earth', 'Golden Dawn / Book T suit-element attribution', 'Original concise learning synthesis; Book T correspondence is tradition-specific, not universal.');
INSERT INTO cards (card_id, card_name, arcana, suit, rank, element, upright_keywords, reversed_keywords, technical_upright, technical_reversed, child_explanation, imagery_observation, reflection_prompt_1, reflection_prompt_2, astrological_correspondence, correspondence_system, source_note) VALUES ('pentacles_02_two_pentacles', 'Two of Pentacles', 'Minor', 'Pentacles', 2, 'Earth', 'Adaptability, priorities, time management, balance', 'Overload, disorganization, poor prioritization', 'Managing changing demands requires flexibility and conscious prioritization.', 'Too many commitments compete for limited energy or time.', 'You are juggling. Decide what matters most and what can wait.', 'A figure juggles two pentacles linked by an infinity ribbon as ships move behind.', 'Which demands compete for my attention?', 'What can be scheduled, simplified, or dropped?', 'Jupiter in Capricorn — decan 1 of 3', 'Golden Dawn / Book T decan attribution', 'Original concise learning synthesis; Book T correspondence is tradition-specific, not universal.');
INSERT INTO cards (card_id, card_name, arcana, suit, rank, element, upright_keywords, reversed_keywords, technical_upright, technical_reversed, child_explanation, imagery_observation, reflection_prompt_1, reflection_prompt_2, astrological_correspondence, correspondence_system, source_note) VALUES ('pentacles_03_three_pentacles', 'Three of Pentacles', 'Minor', 'Pentacles', 3, 'Earth', 'Craft, collaboration, skill, constructive feedback', 'Poor teamwork, weak standards, unrecognized contribution', 'Skill develops through practice, feedback and coordinated work.', 'Roles or standards are unclear, or collaboration is not functioning.', 'Good work gets better when people practice and help each other.', 'A craftsperson works while two people discuss a design.', 'Which skill needs deliberate practice?', 'Whose feedback would improve the work?', 'Mars in Capricorn — decan 2 of 3', 'Golden Dawn / Book T decan attribution', 'Original concise learning synthesis; Book T correspondence is tradition-specific, not universal.');
INSERT INTO cards (card_id, card_name, arcana, suit, rank, element, upright_keywords, reversed_keywords, technical_upright, technical_reversed, child_explanation, imagery_observation, reflection_prompt_1, reflection_prompt_2, astrological_correspondence, correspondence_system, source_note) VALUES ('pentacles_04_four_pentacles', 'Four of Pentacles', 'Minor', 'Pentacles', 4, 'Earth', 'Security, saving, control, conservation', 'Possessiveness, fear of loss, excessive control', 'Protecting resources can be sensible, but excessive holding restricts growth.', 'Fear of losing control blocks circulation, generosity or change.', 'Keeping things safe matters, but holding too tightly can stop growth.', 'A figure holds a pentacle while two more are underfoot and one rests on the head.', 'What am I trying to protect?', 'Where is protection becoming control?', 'Sun in Capricorn — decan 3 of 3', 'Golden Dawn / Book T decan attribution', 'Original concise learning synthesis; Book T correspondence is tradition-specific, not universal.');
INSERT INTO cards (card_id, card_name, arcana, suit, rank, element, upright_keywords, reversed_keywords, technical_upright, technical_reversed, child_explanation, imagery_observation, reflection_prompt_1, reflection_prompt_2, astrological_correspondence, correspondence_system, source_note) VALUES ('pentacles_05_five_pentacles', 'Five of Pentacles', 'Minor', 'Pentacles', 5, 'Earth', 'Scarcity, hardship, exclusion, material worry', 'Recovery, assistance, rebuilding, renewed support', 'Material or social difficulty can create a feeling of being shut out; help may be available.', 'Recovery, seeking assistance, or gradual rebuilding after hardship; sometimes refusal of help.', 'You are outside in the cold, but there may be a warm place and people who can help.', 'Two figures walk through snow beside a lit stained-glass window.', 'Where do I feel unsupported or resource-constrained?', 'What support could I ask for or accept?', 'Mercury in Taurus — decan 1 of 3', 'Golden Dawn / Book T decan attribution', 'Original concise learning synthesis; Book T correspondence is tradition-specific, not universal.');
INSERT INTO cards (card_id, card_name, arcana, suit, rank, element, upright_keywords, reversed_keywords, technical_upright, technical_reversed, child_explanation, imagery_observation, reflection_prompt_1, reflection_prompt_2, astrological_correspondence, correspondence_system, source_note) VALUES ('pentacles_06_six_pentacles', 'Six of Pentacles', 'Minor', 'Pentacles', 6, 'Earth', 'Generosity, exchange, support, fairness', 'Unequal exchange, strings attached, dependency', 'Resources are shared or exchanged; examine fairness and power in the arrangement.', 'Giving creates control, receiving feels conditional, or exchange is uneven.', 'Help should be fair. Notice whether both people are respected.', 'A wealthy figure gives coins to two people while holding scales.', 'Where is support being given or received?', 'Is this exchange fair and freely chosen?', 'Moon in Taurus — decan 2 of 3', 'Golden Dawn / Book T decan attribution', 'Original concise learning synthesis; Book T correspondence is tradition-specific, not universal.');
INSERT INTO cards (card_id, card_name, arcana, suit, rank, element, upright_keywords, reversed_keywords, technical_upright, technical_reversed, child_explanation, imagery_observation, reflection_prompt_1, reflection_prompt_2, astrological_correspondence, correspondence_system, source_note) VALUES ('pentacles_07_seven_pentacles', 'Seven of Pentacles', 'Minor', 'Pentacles', 7, 'Earth', 'Patience, evaluation, investment, long-term effort', 'Impatience, poor return, reassessment', 'Review the results of sustained effort before deciding whether to continue or adjust.', 'Effort may not be producing useful results, or impatience obscures progress.', 'You planted something. Check how it is growing before changing the plan.', 'A worker leans on a tool and looks at a plant bearing pentacles.', 'What investment needs evaluation?', 'What evidence would justify continuing or changing course?', 'Saturn in Taurus — decan 3 of 3', 'Golden Dawn / Book T decan attribution', 'Original concise learning synthesis; Book T correspondence is tradition-specific, not universal.');
INSERT INTO cards (card_id, card_name, arcana, suit, rank, element, upright_keywords, reversed_keywords, technical_upright, technical_reversed, child_explanation, imagery_observation, reflection_prompt_1, reflection_prompt_2, astrological_correspondence, correspondence_system, source_note) VALUES ('pentacles_08_eight_pentacles', 'Eight of Pentacles', 'Minor', 'Pentacles', 8, 'Earth', 'Practice, apprenticeship, quality, concentration', 'Perfectionism, boredom, careless work', 'Skill and reliability grow through focused repetition and feedback.', 'Repetition lacks purpose, quality falls, or perfectionism slows completion.', 'Practice one skill carefully, again and again.', 'A craftsperson engraves pentacles at a workbench.', 'Which skill deserves focused repetition?', 'What standard is good enough for this stage?', 'Sun in Virgo — decan 1 of 3', 'Golden Dawn / Book T decan attribution', 'Original concise learning synthesis; Book T correspondence is tradition-specific, not universal.');
INSERT INTO cards (card_id, card_name, arcana, suit, rank, element, upright_keywords, reversed_keywords, technical_upright, technical_reversed, child_explanation, imagery_observation, reflection_prompt_1, reflection_prompt_2, astrological_correspondence, correspondence_system, source_note) VALUES ('pentacles_09_nine_pentacles', 'Nine of Pentacles', 'Minor', 'Pentacles', 9, 'Earth', 'Self-sufficiency, comfort, independence, cultivated success', 'Dependence, overwork, fragile security', 'Enjoying the results of disciplined work and developing independent capacity.', 'Security depends too heavily on appearances, or independence feels isolating.', 'Enjoy what you have built, and remember to enjoy your life too.', 'A well-dressed figure stands in a vineyard with a falcon.', 'What have I built through my own effort?', 'What does sustainable independence require?', 'Venus in Virgo — decan 2 of 3', 'Golden Dawn / Book T decan attribution', 'Original concise learning synthesis; Book T correspondence is tradition-specific, not universal.');
INSERT INTO cards (card_id, card_name, arcana, suit, rank, element, upright_keywords, reversed_keywords, technical_upright, technical_reversed, child_explanation, imagery_observation, reflection_prompt_1, reflection_prompt_2, astrological_correspondence, correspondence_system, source_note) VALUES ('pentacles_10_ten_pentacles', 'Ten of Pentacles', 'Minor', 'Pentacles', 10, 'Earth', 'Legacy, stability, family, long-term wealth', 'Instability, family tension, fragile foundations', 'Long-term security is connected to shared resources, institutions and legacy.', 'Family or financial structures need review; inherited expectations may not fit.', 'Think about what you are building for the long term.', 'Several generations and dogs gather beneath an arch with ten pentacles.', 'What am I building for the long term?', 'Which inherited expectations do I want to keep or change?', 'Mercury in Virgo — decan 3 of 3', 'Golden Dawn / Book T decan attribution', 'Original concise learning synthesis; Book T correspondence is tradition-specific, not universal.');
INSERT INTO cards (card_id, card_name, arcana, suit, rank, element, upright_keywords, reversed_keywords, technical_upright, technical_reversed, child_explanation, imagery_observation, reflection_prompt_1, reflection_prompt_2, astrological_correspondence, correspondence_system, source_note) VALUES ('pentacles_11_page_pentacles', 'Page of Pentacles', 'Minor', 'Pentacles', 11, 'Earth', 'Study, practicality, curiosity, new skill', 'Procrastination, lack of follow-through, poor planning', 'A practical learner begins a skill or opportunity with attention and patience.', 'Interest is not translated into a routine or concrete plan.', 'Start learning something useful and practice it a little each day.', 'A young figure studies a pentacle in a green field.', 'What practical skill should I begin learning?', 'What routine would make learning consistent?', 'Court elemental formula: Earth of Earth; no single zodiac sign assigned in this base model', 'Golden Dawn court elemental formula; sign attribution intentionally omitted', 'Original concise learning synthesis; Book T correspondence is tradition-specific, not universal.');
INSERT INTO cards (card_id, card_name, arcana, suit, rank, element, upright_keywords, reversed_keywords, technical_upright, technical_reversed, child_explanation, imagery_observation, reflection_prompt_1, reflection_prompt_2, astrological_correspondence, correspondence_system, source_note) VALUES ('pentacles_12_knight_pentacles', 'Knight of Pentacles', 'Minor', 'Pentacles', 12, 'Earth', 'Reliability, routine, diligence, steady progress', 'Stagnation, rigidity, perfectionism, slow movement', 'Consistent work and dependable routines create gradual progress.', 'Routine becomes inflexible or caution prevents necessary movement.', 'Keep showing up, but check that your effort is taking you somewhere.', 'A still armored rider sits on a heavy horse holding a pentacle.', 'Which routine reliably moves me forward?', 'Where do I need to adapt rather than repeat?', 'Court elemental formula: Air of Earth; no single zodiac sign assigned in this base model', 'Golden Dawn court elemental formula; sign attribution intentionally omitted', 'Original concise learning synthesis; Book T correspondence is tradition-specific, not universal.');
INSERT INTO cards (card_id, card_name, arcana, suit, rank, element, upright_keywords, reversed_keywords, technical_upright, technical_reversed, child_explanation, imagery_observation, reflection_prompt_1, reflection_prompt_2, astrological_correspondence, correspondence_system, source_note) VALUES ('pentacles_13_queen_pentacles', 'Queen of Pentacles', 'Minor', 'Pentacles', 13, 'Earth', 'Practical care, resourcefulness, stability, embodiment', 'Self-neglect, overgiving, insecurity, material worry', 'Practical nurturing integrates resources, body, work and care.', 'Care for others or material security crowds out personal needs.', 'Take care of your body, resources and people without forgetting yourself.', 'A queen holds a pentacle in a fertile garden.', 'What practical care do I need today?', 'Where is my care for others exceeding my capacity?', 'Court elemental formula: Water of Earth; no single zodiac sign assigned in this base model', 'Golden Dawn court elemental formula; sign attribution intentionally omitted', 'Original concise learning synthesis; Book T correspondence is tradition-specific, not universal.');
INSERT INTO cards (card_id, card_name, arcana, suit, rank, element, upright_keywords, reversed_keywords, technical_upright, technical_reversed, child_explanation, imagery_observation, reflection_prompt_1, reflection_prompt_2, astrological_correspondence, correspondence_system, source_note) VALUES ('pentacles_14_king_pentacles', 'King of Pentacles', 'Minor', 'Pentacles', 14, 'Earth', 'Stewardship, competence, prosperity, grounded leadership', 'Materialism, rigidity, risk aversion, misuse of resources', 'Responsible management of resources and systems supports sustainable results.', 'Security becomes possessiveness or status replaces sound stewardship.', 'Manage what you have wisely and build something that can last.', 'A king sits among vines and pentacle motifs with a scepter.', 'What resource needs better stewardship?', 'How can I measure success beyond material status?', 'Court elemental formula: Fire of Earth; no single zodiac sign assigned in this base model', 'Golden Dawn court elemental formula; sign attribution intentionally omitted', 'Original concise learning synthesis; Book T correspondence is tradition-specific, not universal.');
INSERT INTO correspondences (layer, tarot_group, element, zodiac_signs, traditional_sign_rulers, scope, system, caution) VALUES ('Suit / element', 'Wands', 'Fire', 'Aries; Leo; Sagittarius', 'Mars; Sun; Jupiter', 'All Wands cards inherit the suit element; Two–Ten receive more specific decan attributions.', 'Golden Dawn / Book T', 'Sign rulers are rulers of the zodiac signs, not planetary rulers of the entire suit.');
INSERT INTO correspondences (layer, tarot_group, element, zodiac_signs, traditional_sign_rulers, scope, system, caution) VALUES ('Suit / element', 'Cups', 'Water', 'Cancer; Scorpio; Pisces', 'Moon; Mars; Jupiter', 'All Cups cards inherit the suit element; Two–Ten receive more specific decan attributions.', 'Golden Dawn / Book T', 'Sign rulers are rulers of the zodiac signs, not planetary rulers of the entire suit.');
INSERT INTO correspondences (layer, tarot_group, element, zodiac_signs, traditional_sign_rulers, scope, system, caution) VALUES ('Suit / element', 'Swords', 'Air', 'Gemini; Libra; Aquarius', 'Mercury; Venus; Saturn', 'All Swords cards inherit the suit element; Two–Ten receive more specific decan attributions.', 'Golden Dawn / Book T', 'Sign rulers are rulers of the zodiac signs, not planetary rulers of the entire suit.');
INSERT INTO correspondences (layer, tarot_group, element, zodiac_signs, traditional_sign_rulers, scope, system, caution) VALUES ('Suit / element', 'Pentacles', 'Earth', 'Taurus; Virgo; Capricorn', 'Venus; Mercury; Saturn', 'All Pentacles cards inherit the suit element; Two–Ten receive more specific decan attributions.', 'Golden Dawn / Book T', 'Sign rulers are rulers of the zodiac signs, not planetary rulers of the entire suit.');
INSERT INTO correspondences (layer, tarot_group, element, zodiac_signs, traditional_sign_rulers, scope, system, caution) VALUES ('Major Arcana', 'Major correspondences', 'Varies / sometimes none', 'Aries, Taurus, Gemini, Cancer, Leo, Virgo, Libra, Scorpio, Sagittarius, Capricorn, Aquarius, Pisces', 'Planets and zodiac signs vary by card', 'Card-specific attributions are listed in cards.csv.', 'Golden Dawn / Book T', 'This is one historical esoteric correspondence system; other decks and schools differ.');
INSERT INTO correspondences (layer, tarot_group, element, zodiac_signs, traditional_sign_rulers, scope, system, caution) VALUES ('Court cards', 'King / Queen / Knight / Page', 'Element of suit + court rank formula', 'Not assigned in this base model', 'Not assigned', 'King=Fire of suit; Queen=Water of suit; Knight=Air of suit; Page=Earth of suit.', 'Golden Dawn court elemental formula', 'Court-card zodiac ranges are complex and tradition-dependent; do not infer a single sign from suit alone.');

COMMIT;


